using Hyper.Domain.Entities.Integrations; using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; namespace Hyper.Infrastructure.Data.Configurations; public sealed class BasalamConnectionConfiguration:IEntityTypeConfiguration<BasalamConnection>{public void Configure(EntityTypeBuilder<BasalamConnection>b){b.ToTable("BasalamConnections");b.HasKey(x=>x.Id);b.Property(x=>x.TenantId).HasMaxLength(30).IsRequired();b.Property(x=>x.BasalamShopId).HasMaxLength(128).IsRequired();b.Property(x=>x.AccessToken).HasColumnType("nvarchar(max)").IsRequired();b.Property(x=>x.RefreshToken).HasColumnType("nvarchar(max)");b.HasIndex(x=>new{x.ShopId,x.BasalamShopId}).IsUnique();}}
